import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,E as n,M as r,N as i,O as a,P as o,S as s,T as c,_ as l,b as u,h as d,k as f,p,v as m,w as h,x as g}from"./shared-DP9JVsk0.js";import{t as _}from"./cloud-BBv7Rv1J.js";import{D as v}from"./index-DLaUeCZy.js";import{t as y}from"./CodeEditor-BZlrvoTL.js";var b=`data:image/svg+xml;base64,`,x=e();function S({module:e}){return(0,x.jsxs)(i,{className:`rich-lesson--client-server`,children:[(0,x.jsx)(r,{chip:e??`Месяц 3 · Блок 9 · Интернет и HTTP`,title:`45. Почему CLI недостаточно: клиент и сервер`,intro:`В прошлом проекте Planner уже умел работать с задачами. Мы вводили команды в терминале, а программа применяла правила и сохраняла результат. Теперь представим, что тот же список хочется открыть в браузере или посмотреть через бота. Как дать этим программам доступ к приложению, не заставляя каждую становиться ещё одним Planner?`,tags:[{icon:(0,x.jsx)(v,{size:14}),label:`от локальной программы к API`},{icon:(0,x.jsx)(_,{size:14}),label:`клиент, сервер и общий источник данных`}]}),(0,x.jsxs)(o,{number:`00`,title:`Когда нужен ещё один способ пользоваться приложением`,children:[(0,x.jsx)(a,{children:`Удобный терминал уже решил нашу первую задачу. Но человек может захотеть работать со списком с телефона, нажимать кнопки в браузере или отправлять команды боту. Меняется способ общения с приложением, а смысл задачи остаётся прежним.`}),(0,x.jsx)(`p`,{children:`Можно написать три отдельные программы. Тогда придётся решать, где у каждой лежат данные и кто проверяет правила. Если браузер разрешает одно, а бот другое, пользователь получает не два интерфейса, а два разных продукта. Нам нужна общая часть, к которой смогут обращаться разные программы.`}),(0,x.jsx)(`p`,{children:`Это похоже на службу бронирования переговорных. Один сотрудник выбирает время на сайте, другой пишет администратору. Способ обращения разный, но расписание должно быть одно. Нельзя независимо обещать одну комнату двум людям на одно время.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Что уже есть`,description:`В Persistent Planner интерфейс CLI вызывает сервис, а сервис работает с хранилищем.`},{title:`Что меняется`,description:`Теперь к приложению хочет обратиться другая программа, а не только его собственный CLI.`},{title:`Что выясним`,description:`Кто принимает просьбу, кто решает, можно ли её выполнить, и откуда берётся результат на экране.`}]}),(0,x.jsx)(`p`,{children:`Работающий сетевой сервер пока не нужен. Сначала разберём модель общения. В примерах будем исследовать знакомый Python-код, а в практике объясним несколько ситуаций своими словами.`})]}),(0,x.jsxs)(o,{number:`01`,title:`Локальный вызов работает внутри своей программы`,children:[(0,x.jsx)(a,{children:`CLI означает Command Line Interface, интерфейс командной строки. Он принимает текстовые команды и показывает результат в терминале. В нашем Persistent Planner команда передавалась локальному PlannerService, а JsonStorage читал или записывал tasks.json.`}),(0,x.jsx)(`p`,{children:`У такого пути есть свои преимущества. Программу удобно запускать на своём компьютере, команды можно повторять, а работу легко включить в скрипт. Но внешний пользователь должен получить проект и разобраться с его запуском. Само наличие CLI ещё не даёт отдельному браузеру способ обратиться к приложению.`}),(0,x.jsx)(`p`,{children:`Внутри Python-программы функция доступна потому, что она определена или импортирована в эту программу. Посмотрим на маленький пример расписания. Что происходит между вызовом функции и появлением строки в терминале?`}),(0,x.jsx)(m,{code:`def format_slots(slots):
    return ", ".join(slots)

slots = ["10:00", "11:00"]
label = format_slots(slots)
print(label)`,steps:[{line:0,note:`Python определяет функцию. Её тело пока не выполняется: вызова ещё не было.`},{line:3,note:`В памяти этой программы появляется список доступного времени.`,vars:{slots:`["10:00", "11:00"]`}},{line:4,note:`Программа вызывает свою функцию и передаёт ей список. Здесь нет обращения к другой программе.`,vars:{slots:`["10:00", "11:00"]`}},{line:1,note:`join соединяет строки через запятую и пробел. Функция возвращает строку вызывающему коду.`,vars:{"возвращаемое значение":`"10:00, 11:00"`}},{line:4,note:`После возврата строка записывается в label.`,vars:{label:`"10:00, 11:00"`}},{line:5,note:`print показывает строку в терминале: 10:00, 11:00. Это локальный вывод, а не ответ браузеру.`,vars:{label:`"10:00, 11:00"`}}]}),(0,x.jsx)(`p`,{children:`Это подготовленный разбор выполнения, не запущенный в странице интерпретатор. Сам пример можно выполнить обычным Python. Важно другое: вызов и функция принадлежат одной программе. Нельзя написать имя этой функции в отдельном браузере и таким образом вызвать её в памяти Python.`}),(0,x.jsx)(n,{tone:`info`,children:`CLI тоже может быть клиентом сетевого приложения. Ограничение относится не ко всем терминальным программам, а к нашему нынешнему пути: он напрямую использует локальные модули. Для отдельного клиента нужен другой способ общения.`})]}),(0,x.jsxs)(o,{number:`02`,title:`Клиент помогает человеку обратиться к приложению`,children:[(0,x.jsx)(a,{children:`Клиентом называют программу, которая начинает обращение к другой программе. В этой роли могут выступать браузер, мобильное приложение, бот или скрипт. Человек выбирает действие, а клиент передаёт его намерение и затем показывает полученный результат.`}),(0,x.jsx)(`p`,{children:`Например, на сайте бронирования клиент показывает расписание, собирает выбранное время и помогает заполнить форму. Он может подсветить незаполненное поле сразу, не ожидая ответа. Это полезно: человек быстрее замечает ошибку.`}),(0,x.jsx)(`p`,{children:`Но удобство формы не делает её окончательным судьёй. Другой клиент может не иметь такой проверки. Пользователь может изменить отправленные данные. Расписание может измениться, пока форма открыта. Поэтому проверка на клиенте помогает человеку, но не заменяет проверку в приложении, которое отвечает за бронь.`}),(0,x.jsx)(u,{question:`На сайте нельзя выбрать уже занятое время. Достаточно ли этого, чтобы исключить неверную бронь через бота?`,options:[`Да, кнопка на сайте защищает все способы обращения`,`Нет, правило нужно проверить и при обработке обращения бота`,`Да, если сайт и бот работают на одном компьютере`],correctIndex:1,explanation:`Ограничение кнопки действует только в этом интерфейсе. Бот обращается другим способом, а время могло измениться. Общая проверка должна действовать независимо от клиента.`}),(0,x.jsx)(`p`,{children:`После обращения работа клиента продолжается. Он показывает подтверждение, обновляет список или объясняет отказ. Но сообщение «готово» на экране должно опираться на результат обработки, а не только на факт нажатия кнопки.`})]}),(0,x.jsxs)(o,{number:`03`,title:`Сервер принимает решение по общим правилам`,children:[(0,x.jsx)(a,{children:`Сервер здесь означает работающую программу, которая принимает обращения клиентов, выполняет нужную работу и возвращает результат. Словом «сервер» также называют компьютер, но сейчас нам важна роль программы, а не характеристики устройства.`}),(0,x.jsx)(`p`,{children:`Серверная часть знает общие правила и текущее состояние приложения. Состояние означает данные о том, что происходит сейчас: какое время свободно, какие брони уже существуют. Обработчик обращения проверяет просьбу по этим данным, а не доверяет старой картинке на экране клиента.`}),(0,x.jsx)(`p`,{children:`Покажем только предметное правило на Python. Функция ниже ещё не является сетевым сервером: она ничего не принимает по сети. Такой код помогает увидеть решение, которое в будущем будет выполняться на серверной стороне.`}),(0,x.jsx)(y,{caption:`Рабочая модель: занять свободное время`,code:`def reserve_slot(slots, time):
    if time not in slots:
        return "Такого времени нет"
    if slots[time] == "занято":
        return "Время уже занято"
    slots[time] = "занято"
    return "Бронь подтверждена"

slots = {"10:00": "свободно", "11:00": "занято"}
print(reserve_slot(slots, "10:00"))
print(slots["10:00"])`}),(0,x.jsx)(`p`,{children:`На входе словарь с текущим расписанием и выбранное время. Ключ выбирает запись, значение описывает её состояние. Сначала функция проверяет, существует ли время и свободно ли оно. Только после этого запись меняется. Пример напечатает «Бронь подтверждена», затем «занято».`}),(0,x.jsx)(`p`,{children:`Теперь переключаем три входа. Ниже показан фрагмент той же функции и подготовленные результаты. Каждый сценарий начинается с исходного расписания из примера, а не продолжает предыдущую бронь.`}),(0,x.jsx)(d,{code:`def reserve_slot(slots, time):
    if time not in slots:
        return "Такого времени нет"
    if slots[time] == "занято":
        return "Время уже занято"
    slots[time] = "занято"
    return "Бронь подтверждена"`,scenarios:[{label:`Выбрано "10:00"`,activeLine:6,output:`Бронь подтверждена. 10:00 теперь занято.`},{label:`Выбрано "11:00"`,activeLine:4,output:`Время уже занято. Расписание не изменилось.`},{label:`Выбрано "12:00"`,activeLine:2,output:`Такого времени нет. Расписание не изменилось.`}]}),(0,x.jsx)(`p`,{children:`Отказ тоже является результатом работы. Вторая бронь не должна появиться только потому, что клиент попросил её создать. Сервер защищает правило приложения и сообщает, почему просьба не выполнена.`}),(0,x.jsx)(n,{tone:`info`,children:`Здесь обращения рассматриваются по очереди. В реальном сервисе одновременное бронирование требует дополнительной защиты от конкурирующих изменений. Этот пример показывает порядок проверки и изменения, а не готовую систему бронирования для production.`})]}),(0,x.jsxs)(o,{number:`04`,title:`Request и response связывают две программы`,children:[(0,x.jsx)(a,{children:`Когда клиент обращается к серверу, между ними проходит сообщение. Request означает запрос: клиент сообщает, чего хочет и какие данные передаёт. Response означает ответ: сервер сообщает результат обработки.`}),(0,x.jsx)(`p`,{children:`API расшифровывается как Application Programming Interface, программный интерфейс приложения. Вообще интерфейс может связывать и части одной программы. В этом курсе речь идёт о внешнем сетевом API: согласованном способе обратиться к приложению, не зная его внутренних Python-функций.`}),(0,x.jsx)(`p`,{children:`HTTP, Hypertext Transfer Protocol, задаёт правила обмена запросами и ответами. Это не библиотека и не название сервера. Как именно устроены сообщения, изучим дальше. Сейчас проследим один разговор: человек выбирает время, клиент передаёт просьбу, сервер принимает решение, клиент показывает полученный ответ.`}),(0,x.jsx)(h,{title:`Собираем путь одной брони`,label:`ПОСЛЕДОВАТЕЛЬНОСТЬ`,prompt:`Каков порядок событий от выбора времени до результата? На каком шаге появляется основание показать человеку итог?`,pieces:[{id:`response`,code:`Сервер отправил response с результатом`},{id:`request`,code:`Клиент отправил request серверу`},{id:`display`,code:`Клиент показал подтверждение или отказ`},{id:`choice`,code:`Человек выбрал время, клиент подготовил просьбу`},{id:`decision`,code:`Сервер проверил расписание и выполнил допустимое действие`}],correctOrder:[`choice`,`request`,`decision`,`response`,`display`],explanation:`Нажатие кнопки ещё не подтверждает бронь. Клиент получает основание показать итог после ответа об обработке. Проверка и допустимое изменение происходят на серверной стороне.`,incorrectExplanation:`Клиент сначала передаёт просьбу. Сервер проверяет её до подтверждения и только затем отвечает. Клиент не может показать итог обработки раньше получения этого ответа.`}),(0,x.jsx)(`p`,{children:`Если время занято, разговор не обрывается на проверке: сервер возвращает отказ, а клиент объясняет его человеку. Если ответ не получен из-за проблем со связью, клиент не знает итог только по этому факту. Нельзя автоматически объявить ни успех, ни отсутствие изменения. Подробности сетевых сбоев пока оставим за рамками занятия.`}),(0,x.jsx)(`p`,{children:`Проверим порядок на знакомом фрагменте функции. Ожидание: попытка занять уже занятое время должна вернуть отказ. Вход содержит запись «занято», но код ниже возвращает подтверждение. Находим причину.`}),(0,x.jsx)(t,{code:`def reserve_slot(slots, time):
    if time not in slots:
        return "Такого времени нет"
    slots[time] = "свободно"
    if slots[time] == "занято":
        return "Время уже занято"
    slots[time] = "занято"
    return "Бронь подтверждена"`,question:`Почему при уже занятом времени функция ошибочно подтверждает бронь?`,options:[`В Python нельзя сравнивать строки в словаре`,`Функция стирает прежнее состояние перед проверкой и сама делает время свободным`,`Любая функция обязана возвращать только True или False`],correctIndex:1,explanation:`Строка slots[time] = «свободно» уничтожает факт существующей брони. Следующая проверка уже не может его обнаружить. Ошибка в порядке работы с данными, а не в сравнении строк.`,fix:`# Убираем сброс состояния перед проверкой.
if slots[time] == "занято":
    return "Время уже занято"
slots[time] = "занято"`}),(0,x.jsx)(`p`,{children:`Исправление показано как фрагмент: оно остаётся внутри функции после проверки существования времени. Сначала узнаём, допустимо ли действие, затем меняем данные. Переименование клиента в браузер или бот этот порядок не меняет.`})]}),(0,x.jsxs)(o,{number:`05`,title:`Два участника не обязательно означают два компьютера`,children:[(0,x.jsx)(a,{children:`Клиент и сервер описывают роли в общении. Во время разработки браузер и Python-сервер могут работать на одном ноутбуке. Между ними всё равно остаётся граница отдельных программ.`}),(0,x.jsx)(`p`,{children:`Процессом называют запущенный экземпляр программы. У Python-сервера своя память. У браузера свои процессы и память. Соседство на одном устройстве не превращает серверную функцию в функцию браузера: для общения нужен предусмотренный способ обмена.`}),(0,x.jsx)(`p`,{children:`Имя localhost указывает на компьютер, с которого выполняется обращение. Если открыть адрес с localhost на телефоне, он относится к самому телефону, а не автоматически к ноутбуку разработчика. Это полезное имя для локальной проверки, но не адрес публикации приложения в интернете.`}),(0,x.jsx)(`p`,{children:`Порт помогает направить сетевое обращение нужной программе. Представим адрес здания и номер кабинета: одного адреса мало, если внутри несколько получателей. У сетевого сервиса роль такого номера выполняет порт. Пока достаточно этой ориентации, команды запуска и настройка будут в следующем блоке.`}),(0,x.jsx)(s,{statement:`Если браузер и Python-сервер работают на одном ноутбуке, браузер может просто вызвать серверную функцию по её имени.`,isTrue:!1,explanation:`Функция находится в памяти другой программы. Один компьютер не отменяет границу процессов. Клиент обращается через внешний интерфейс, а сервер сам вызывает нужную функцию.`})]}),(0,x.jsxs)(o,{number:`06`,title:`Два клиента обращаются к одному приложению`,children:[(0,x.jsx)(a,{children:`Браузер может показывать расписание клетками, а бот присылать текст. Один интерфейс удобно нажимать, другой удобно использовать в переписке. Эти различия полезны и не требуют двух независимых расписаний.`}),(0,x.jsx)(`p`,{children:`Оба клиента обращаются к одному серверу по одному договору. Под договором понимаем согласованные правила общения: какие просьбы приложение принимает и как сообщает результат. Клиенту не требуется знать, какая функция проверила бронь и как устроено хранение внутри.`}),(0,x.jsx)(`p`,{children:`На схеме у каждого клиента своя пара сообщений. Прослеживаем верхнюю пару для браузера, затем нижнюю для бота. Ответ в каждом разговоре возвращается отправителю запроса. Правила и состояние находятся на общей серверной стороне.`}),(0,x.jsxs)(`figure`,{className:`lesson-infographic`,children:[(0,x.jsx)(`img`,{src:b,alt:`Браузер и бот обращаются к одному API-серверу. У каждого клиента своя пара: запрос к серверу и ответ обратно тому же клиенту. Сервер применяет общие правила и управляет состоянием.`,width:1672,height:836,loading:`lazy`,decoding:`async`}),(0,x.jsx)(`figcaption`,{children:`Общие правила и состояние, разные интерфейсы. Ответ браузеру не становится автоматически ответом боту.`})]}),(0,x.jsx)(`p`,{children:`У клиента и сервера разные обязанности. Какому участнику соответствует каждый пример?`}),(0,x.jsx)(p,{prompt:`Кто отвечает за каждую из этих задач?`,leftTitle:`Пример`,rightTitle:`Ответственность`,pairs:[{left:`Показать расписание клетками или текстом`,right:`Клиент: удобный интерфейс`},{left:`Не дать повторно занять уже занятое время`,right:`Сервер: общее правило`}],explanation:`Вид расписания можно менять в отдельном клиенте. Проверка допустимости брони остаётся общей и не зависит от расположения кнопок.`}),(0,x.jsx)(`p`,{children:`Так устроены, например, сервисы с сайтом и мобильным приложением: интерфейсы отличаются, а предметные действия согласованы. В нашем Planner сохранится один набор правил и данных. Позже к CLI добавится HTTP-вход, который будет обращаться к той же логике.`})]}),(0,x.jsxs)(o,{number:`07`,title:`Копия на экране может устареть`,children:[(0,x.jsx)(a,{children:`Общий источник данных не означает, что все экраны всегда показывают одно и то же. Клиент получает сведения в определённый момент. Если позже другой клиент что-то изменил, прежнее отображение может остаться без обновления.`}),(0,x.jsx)(`p`,{children:`Представим: браузер получил свободное время и оставил расписание открытым. Бот затем занял это время, сервер подтвердил бронь именно боту. Ответ боту сам по себе не сообщает браузеру, что его данные устарели.`}),(0,x.jsx)(`p`,{children:`Проверим эту мысль знакомым словарём. Это модель отдельных копий в одной Python-программе, не сетевой обмен. В настоящем приложении клиент получает данные в сообщении, а не читает серверную переменную.`}),(0,x.jsx)(l,{code:`server_slots = {"10:00": "свободно"}
browser_slots = server_slots.copy()
server_slots["10:00"] = "занято"
print(browser_slots["10:00"])
print(server_slots["10:00"])`,output:`свободно
занято`,hint:`copy создаёт другой словарь. Значения здесь строки, общих вложенных изменяемых объектов нет.`}),(0,x.jsx)(`p`,{children:`Изменился server_slots, а browser_slots остался прежним. Первая строка вывода описывает сохранённую копию, вторая текущее состояние модели сервера. Два значения не доказывают, что бронь не состоялась: они получены в разное время.`}),(0,x.jsx)(`p`,{children:`Источником истины называют место, по которому определяют актуальное состояние приложения. В нашей модели это серверная сторона. Экран хранит удобное для показа представление, но не становится главным расписанием.`}),(0,x.jsx)(`p`,{children:`Для обновления браузер может снова запросить данные. Когда и как это происходит, зависит от устройства клиента. Некоторые приложения получают уведомления об изменениях, но здесь мы их не реализуем. Важно не обещать автоматическую синхронизацию только потому, что сервер общий.`}),(0,x.jsx)(g,{question:`Браузер всё ещё показывает свободное время, хотя бот получил подтверждение брони. Почему эти факты не противоречат друг другу?`,answer:(0,x.jsx)(`p`,{children:`Браузер показывает сведения, полученные раньше. Сервер изменил состояние и ответил боту. Пока браузер не получил свежие данные, его экран может отставать от текущего расписания.`})})]}),(0,x.jsxs)(o,{number:`08`,title:`Доступ к данным не равен доступу к файлу`,children:[(0,x.jsx)(a,{children:`В локальном Planner JsonStorage работал с tasks.json. Легко представить следующий шаг так: «пусть браузер тоже откроет этот файл». Но файл хранения и внешний интерфейс приложения решают разные задачи.`}),(0,x.jsx)(`p`,{children:`Хранилище обслуживает внутреннюю работу программы. API принимает просьбу, даёт применить правила и возвращает нужный результат. Если клиент напрямую меняет файл, он может обойти правила и начинает зависеть от пути, формата и устройства хранения.`}),(0,x.jsx)(`p`,{children:`Это как общий журнал бронирования. Посетителю можно дать понятный способ попросить комнату. Если вместо этого каждый сам исправляет страницы журнала, никто не контролирует, допустима ли запись. Право попросить действие не означает право менять внутренние записи как угодно.`}),(0,x.jsx)(c,{question:`Сервис заменил внутренний файл хранилищем другого вида, но сохранил внешний договор. Какому клиенту не нужно знать о такой замене?`,left:{title:`Клиент читает файл сервера`,code:`Открыть конкретный путь и разобратьего 
содержимое`,note:`Клиент привязан к способу хранения.`},right:{title:`Клиент обращается через API`,code:`Попросить сведения и получить согласованный 
ответ`,note:`Способ хранения остаётся за внешней границей.`},preferred:`right`,explanation:`Если договор сохранён, клиент API продолжает общаться прежним способом. Прямой читатель файла зависит от его существования и структуры. Речь не о запрете любых файловых интерфейсов, а о границе нашего сетевого приложения.`}),(0,x.jsx)(`p`,{children:`JSON задаёт формат данных, но не требует хранить их именно в файле. В нашем Planner существующий tasks.json останется внутренним хранилищем: JsonStorage будет читать и сохранять его, а API обратится к хранилищу через PlannerService. Клиент получит согласованный ответ, но не доступ к пути или внутреннему формату файла.`})]}),(0,x.jsxs)(o,{number:`09`,title:`Тот же Planner, новая точка входа`,children:[(0,x.jsx)(a,{children:`Persistent Planner не выбрасываем и не переписываем. CLI, PlannerService и JsonStorage остаются частями проекта. Меняется способ обратиться к уже знакомым операциям.`}),(0,x.jsx)(`p`,{children:`В этом блоке мы разбираем договор между клиентом и сервером, поэтому пока не меняем код. После HTTP-подготовки добавим FastAPI-интерфейс к существующему PlannerService. Браузер и бот будут обращаться к серверу, а сервер передаст действие знакомой логике Planner.`}),(0,x.jsx)(f,{items:[{title:`Один проект`,description:`CLI остаётся на месте. FastAPI станет ещё одним входом в тот же Persistent Planner.`},{title:`Общие правила`,description:`HTTP-обработчик передаст операцию существующему PlannerService, а не создаст собственные правила.`},{title:`Общие данные`,description:`JsonStorage продолжит читать и сохранять тот же tasks.json. Клиент не открывает файл напрямую.`}]}),(0,x.jsx)(y,{caption:`Существующий проект и будущий HTTP-вход`,code:`Сейчас: CLI → PlannerService → JsonStorage → tasks.json
Позже: HTTP-клиент → FastAPI → тот же PlannerService
                                      ↓
                                  JsonStorage → тот же tasks.json`}),(0,x.jsx)(`p`,{children:`Источник актуального состояния и долговечность данных связаны, но это разные свойства. PlannerService получает текущее состояние через JsonStorage, а файл сохраняется между запусками. Браузер же может временно показывать старую копию, пока не запросит свежий ответ API.`}),(0,x.jsx)(`p`,{children:`В блоке 9 разбираем HTTP-договор и не меняем Persistent Planner. После его завершения в следующем блоке добавим FastAPI к существующему сервису и хранилищу. Следующее занятие уточнит, какие части входят в сообщение клиента.`})]}),(0,x.jsxs)(o,{number:`10`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(a,{children:`Перенесём модель на знакомые задачи Planner. Практика остаётся устной: достаточно разобрать ситуации и обосновать вывод. Документ, сервер и знание номеров HTTP-статусов не требуются.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Сравнить пути`,description:`Проследить чтение списка через прежний CLI и через будущего отдельного клиента.`},{title:`Разобрать действие`,description:`Рассмотреть создание задачи при двух разных вводах и объяснить последствия.`},{title:`Связать клиентов`,description:`Сравнить браузер и бот, затем разобрать экран, который ещё не получил новое состояние.`},{title:`Проверить границу`,description:`Оценить предложения о доступе к хранению и о зависимости сервера от кнопок.`}]}),(0,x.jsx)(`p`,{children:`В каждом сценарии важна причинная цепочка: кто начал действие, кто получил данные, на каком основании принято решение и что увидит человек. Последний сценарий показывает последствия неверного разделения обязанностей.`}),(0,x.jsx)(`p`,{children:`К завершению занятия мы объясняем путь обращения и отличаем актуальные данные от копии на экране. Структуру HTTP-запроса, адреса операций и серверный код пока не разбираем.`})]})]})}export{S as Lesson45};